
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../core/widgets/n_card.dart';
import '../../../core/theme/app_colors.dart';
import '../../../data/models/app_models.dart';
import '../providers/finance_provider.dart';
class BudgetsScreen extends ConsumerWidget { const BudgetsScreen({super.key}); @override Widget build(BuildContext context, WidgetRef ref){ final budgets=ref.watch(budgetsProvider); final trans=ref.watch(transProvider); return Scaffold(appBar: AppBar(title: const Text('الميزانيات')), body: ListView.builder(padding: const EdgeInsets.all(16), itemCount: budgets.length, itemBuilder: (_,i){ final b=budgets[i]; final spent=trans.where((t)=>t.category==b.category && t.type=='expense').fold(0.0,(a,x)=>a+x.amount); final pct=(spent/b.limit).clamp(0,1).toDouble(); return Padding(padding: const EdgeInsets.only(bottom:12), child: NCard(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children:[Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children:[Text(b.category, style: const TextStyle(fontWeight: FontWeight.w800)), Text('\${spent.toStringAsFixed(0)}/\${b.limit.toStringAsFixed(0)}', style: const TextStyle(color:Colors.grey, fontSize:12))]), const SizedBox(height:12), LinearProgressIndicator(value:pct, backgroundColor:Colors.grey.shade200, valueColor: AlwaysStoppedAnimation(pct>0.9? Colors.red: pct>0.7? AppColors.warning: AppColors.secondary), borderRadius: BorderRadius.circular(8), minHeight:8)]))); }), floatingActionButton: FloatingActionButton(backgroundColor:AppColors.warning, foregroundColor:Colors.white, onPressed: ()=>_add(context, ref), child: const Icon(Icons.add))); } void _add(BuildContext ctx, WidgetRef ref){ final cat=TextEditingController(); final lim=TextEditingController(); showDialog(context: ctx, builder: (_)=> AlertDialog(title: const Text('ميزانية جديدة'), content: Column(mainAxisSize:MainAxisSize.min, children:[TextField(controller:cat, decoration: const InputDecoration(labelText:'التصنيف')), TextField(controller:lim, keyboardType: TextInputType.number, decoration: const InputDecoration(labelText:'الحد'))]), actions:[TextButton(onPressed: ()=>Navigator.pop(ctx), child: const Text('إلغاء')), ElevatedButton(onPressed:(){ final b=BudgetModel.create(cat.text, double.tryParse(lim.text)??0); ref.read(budgetsProvider.notifier).add(b); Navigator.pop(ctx);}, child: const Text('إضافة'))])); } }
